from AlgorithmImports import *
import math
from collections import deque


class ParallelSlotAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.allSymbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spyCloseHistory = deque(maxlen=2)
        self.smaHistory = deque(maxlen=2)
        self.aaplCloseHistory = deque(maxlen=4)

        self.lotA = 0
        self.lotB = 0

    def OnData(self, data: Slice):
        if data.ContainsKey(self.spy) and data[self.spy] is not None:
            self.spyCloseHistory.append(data[self.spy].Close)
            if self.sma.IsReady:
                self.smaHistory.append(self.sma.Current.Value)

        if data.ContainsKey(self.aapl) and data[self.aapl] is not None:
            self.aaplCloseHistory.append(data[self.aapl].Close)

        for symbol in self.allSymbols:
            if not data.ContainsKey(symbol) or data[symbol] is None:
                return

        if not self.sma.IsReady or not self.rsi.IsReady:
            return

        if len(self.spyCloseHistory) < 2 or len(self.smaHistory) < 2 or len(self.aaplCloseHistory) < 4:
            return

        self.RunStrategyA(data)
        self.RunStrategyB(data)

    def RunStrategyA(self, data):
        todayClose = self.spyCloseHistory[-1]
        yesterdayClose = self.spyCloseHistory[-2]
        todaySma = self.smaHistory[-1]
        yesterdaySma = self.smaHistory[-2]

        crossAbove = yesterdayClose <= yesterdaySma and todayClose > todaySma
        crossBelow = yesterdayClose >= yesterdaySma and todayClose < todaySma

        if self.lotA > 0:
            if crossBelow:
                self.MarketOrder(self.spy, -self.lotA)
                self.lotA = 0
        else:
            if crossAbove:
                price = data[self.spy].Close
                targetValue = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = math.floor(targetValue / price)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lotA = shares

    def RunStrategyB(self, data):
        if self.lotB > 0:
            if self.rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lotB)
                self.lotB = 0
        else:
            closes = list(self.aaplCloseHistory)
            redStreak = closes[0] > closes[1] > closes[2] > closes[3]
            if redStreak:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    price = data[self.aapl].Close
                    shares = math.floor(20000 / price)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB = shares

