from AlgorithmImports import *


class TwoSlotParallelStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.all_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma_period = 20
        self.sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)

        self.rsi_period = 14
        self.rsi = self.RSI(self.aapl, self.rsi_period, MovingAverageType.Wilder, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.all_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # Slot 1 - Strategy A (SPY)
        if self.sma.IsReady and self.spy_prev_sma is not None and self.spy_prev_close is not None:
            sma_today = self.sma.Current.Value
            crossed_above = self.spy_prev_close <= self.spy_prev_sma and spy_close > sma_today
            crossed_below = self.spy_prev_close >= self.spy_prev_sma and spy_close < sma_today

            lot_a = self.Portfolio[self.spy].Quantity

            if lot_a > 0:
                if crossed_below:
                    self.Liquidate(self.spy)
            else:
                if crossed_above:
                    target_value = 0.4 * self.Portfolio.TotalPortfolioValue
                    qty = int(target_value // spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)

        # Slot 2 - Strategy B (AAPL)
        if self.rsi.IsReady and self.aapl_prev_close is not None:
            lot_b = self.Portfolio[self.aapl].Quantity

            if lot_b > 0:
                if self.rsi.Current.Value > 60:
                    self.Liquidate(self.aapl)
            else:
                if self.aapl_red_streak >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        qty = int(20000 // aapl_close)
                        if qty > 0:
                            self.MarketOrder(self.aapl, qty)

        self.spy_prev_close = spy_close
        self.spy_prev_sma = self.sma.Current.Value if self.sma.IsReady else None
        self.aapl_prev_close = aapl_close

