                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady
        have_prev = self.prev_spy_close is not None and self.prev_spy_sma is not None

        if indicators_ready and have_prev:
            spy_sma_val = self.spy_sma.Current.Value
            rsi_val = self.aapl_rsi.Current.Value

            # Slot 1 - Strategy A (SPY): sell before buy
            spy_qty = self.Portfolio[self.spy].Quantity
