                crosses_above = self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma_val
                if crosses_above:
                    self.SetHoldings(self.spy, 0.4)

            # Slot 2 - Strategy B (AAPL): sell before buy
            aapl_qty = self.Portfolio[self.aapl].Quantity
            if aapl_qty > 0:
                if rsi_val > 60:
                    self.Liquidate(self.aapl)
            else:
                if self.aapl_red_streak >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        qty = math.floor(20000 / aapl_close)
                        if qty > 0:
                            self.MarketOrder(self.aapl, qty)

        self.prev_spy_close = spy_close
