class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA period not specified in the spec; using 50 as a standard trend-following default
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_lot_qty = 0
        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_lot_qty = 0
        self.aapl_prev_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        for symbol in self.required_symbols:
            if not data.Bars.ContainsKey(symbol):
                return

        self._process_strategy_a(data)
        self._process_strategy_b(data)

    def _process_strategy_a(self, data):
        close = data.Bars[self.spy].Close

        if self.spy_sma.IsReady:
            sma_val = self.spy_sma.Current.Value

            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                if self.spy_lot_qty > 0:
                    crossed_below = self.spy_prev_close >= self.spy_prev_sma and close < sma_val
                    if crossed_below:
                        self.MarketOrder(self.spy, -self.spy_lot_qty)
                        self.spy_lot_qty = 0

                if self.spy_lot_qty == 0:
                    crossed_above = self.spy_prev_close <= self.spy_prev_sma and close > sma_val
                    if crossed_above:
                        portfolio_value = self.Portfolio.TotalPortfolioValue
                        target_value = 0.4 * portfolio_value
                        qty = math.floor(target_value / close)
                        if qty > 0:
                            self.MarketOrder(self.spy, qty)
                            self.spy_lot_qty = qty

            self.spy_prev_sma = sma_val

        self.spy_prev_close = close

    def _process_strategy_b(self, data):
        close = data.Bars[self.aapl].Close

        if self.aapl_prev_close is not None:
            if close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.aapl_lot_qty > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot_qty)
                self.aapl_lot_qty = 0

        if self.aapl_lot_qty == 0 and self.aapl_red_streak >= 3:
            cash = self.Portfolio.Cash
            if cash >= 20000:
                qty = math.floor(20000 / close)
                if qty > 0:
                    self.MarketOrder(self.aapl, qty)
                    self.aapl_lot_qty = qty

        self.aapl_prev_close = close

