import math
from AlgorithmImports import *


class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in tickers:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spySma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aaplRsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spyPrevClose = None
        self.spyPrevSma = None
        self.spyPrevSmaReady = False

        self.aaplPrevClose = None
        self.aaplRedStreak = 0

        self.lotA = 0
        self.lotB = 0

    def OnData(self, data):
        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                return

        spyBar = data.Bars[self.spy]
        aaplBar = data.Bars[self.aapl]

        spyClose = spyBar.Close
        aaplClose = aaplBar.Close

        if self.aaplPrevClose is not None:
            if aaplClose < self.aaplPrevClose:
                self.aaplRedStreak += 1
            else:
                self.aaplRedStreak = 0

        spySmaReadyNow = self.spySma.IsReady
        canCheckSpyCross = (
            spySmaReadyNow
            and self.spyPrevSmaReady
            and self.spyPrevClose is not None
            and self.spyPrevSma is not None
        )

        aaplRsiReady = self.aaplRsi.IsReady

        # --- Sells before buys ---
        if canCheckSpyCross and self.lotA > 0:
            spySmaValue = self.spySma.Current.Value
            crossBelow = self.spyPrevClose >= self.spyPrevSma and spyClose < spySmaValue
            if crossBelow:
                self.MarketOrder(self.spy, -self.lotA)
                self.lotA = 0

        if aaplRsiReady and self.lotB > 0:
            if self.aaplRsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lotB)
                self.lotB = 0

        if canCheckSpyCross and self.lotA == 0:
            spySmaValue = self.spySma.Current.Value
            crossAbove = self.spyPrevClose <= self.spyPrevSma and spyClose > spySmaValue
            if crossAbove:
                investAmount = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = math.floor(investAmount / spyClose)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lotA = shares

        if self.lotB == 0:
            if self.aaplRedStreak >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = math.floor(20000 / aaplClose)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB = shares

        self.spyPrevClose = spyClose
        if spySmaReadyNow:
            self.spyPrevSma = self.spySma.Current.Value
        self.spyPrevSmaReady = spySmaReadyNow

        self.aaplPrevClose = aaplClose

