class TwoSlotParallelStrategiesAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # SMA length unspecified in the strategy spec; using common default of 50 days
        self.spySma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aaplRsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spyPrevClose = None
        self.spyPrevSma = None

        self.aaplPrevClose = None
        self.aaplRedStreak = 0

        self.aaplBuyCash = 20000.0
        self.spyInvestPct = 0.40

    def OnData(self, data: Slice):
        # ---- Continuous market-state updates (independent of other tickers' data presence) ----
        spyCrossAbove = False
        spyCrossBelow = False
        if data.ContainsKey(self.spy) and data[self.spy] is not None:
            spyClose = data[self.spy].Close
            if self.spySma.IsReady and self.spyPrevClose is not None and self.spyPrevSma is not None:
                spyCrossAbove = (self.spyPrevClose <= self.spyPrevSma) and (spyClose > self.spySma.Current.Value)
                spyCrossBelow = (self.spyPrevClose >= self.spyPrevSma) and (spyClose < self.spySma.Current.Value)
            if self.spySma.IsReady:
                self.spyPrevClose = spyClose
                self.spyPrevSma = self.spySma.Current.Value

        aaplRedComplete = False
        if data.ContainsKey(self.aapl) and data[self.aapl] is not None:
            aaplClose = data[self.aapl].Close
            if self.aaplPrevClose is not None and aaplClose < self.aaplPrevClose:
                self.aaplRedStreak += 1
            else:
                self.aaplRedStreak = 0
            self.aaplPrevClose = aaplClose
            if self.aaplRedStreak >= 3:
                aaplRedComplete = True

        # ---- Skip all rule evaluation/action for the day if any subscribed ticker's bar is missing ----
        allPresent = all(data.ContainsKey(s) and data[s] is not None for s in self.symbols)
        if not allPresent:
            return

        # ---- Slot 2: Strategy B (AAPL) ---- sell before buy
        aaplQty = self.Portfolio[self.aapl].Quantity
        if aaplQty > 0:
            if self.aaplRsi.IsReady and self.aaplRsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -aaplQty)
        else:
            if aaplRedComplete:
                cash = self.Portfolio.Cash
                if cash >= self.aaplBuyCash:
                    price = data[self.aapl].Close
                    qty = int(self.aaplBuyCash // price)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)

        # ---- Slot 1: Strategy A (SPY) ---- sell before buy
        spyQty = self.Portfolio[self.spy].Quantity
        if spyQty > 0:
            if spyCrossBelow:
                self.MarketOrder(self.spy, -spyQty)
        else:
            if spyCrossAbove:
                targetValue = self.Portfolio.TotalPortfolioValue * self.spyInvestPct
                price = data[self.spy].Close
                qty = int(targetValue // price)
                if qty > 0:
                    self.MarketOrder(self.spy, qty)

