class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Moving average period unspecified by the strategy definition; using a standard 50-day SMA.
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A (SPY) state
        self.shares_a = 0
        self.prev_spy_close = None
        self.prev_spy_sma = None

        # Strategy B (AAPL) state
        self.shares_b = 0
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, slice):
        spy_present = slice.Bars.ContainsKey(self.spy)
        aapl_present = slice.Bars.ContainsKey(self.aapl)
        all_present = all(slice.Bars.ContainsKey(s) for s in self.symbols)

        # Continuously update market-state quantities (streaks, cross inputs) from available data.
        aapl_close = None
        if aapl_present:
            aapl_close = slice.Bars[self.aapl].Close
            if self.prev_aapl_close is not None:
                if aapl_close < self.prev_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        spy_cross_above = False
        spy_cross_below = False
        spy_close = None
        spy_sma_val = None
        if spy_present:
            spy_close = slice.Bars[self.spy].Close
            if self.spy_sma.IsReady:
                spy_sma_val = self.spy_sma.Current.Value
                if self.prev_spy_close is not None and self.prev_spy_sma is not None:
                    spy_cross_above = (self.prev_spy_close <= self.prev_spy_sma) and (spy_close > spy_sma_val)
                    spy_cross_below = (self.prev_spy_close >= self.prev_spy_sma) and (spy_close < spy_sma_val)

        if all_present:
            # Strategy A (SPY) - sell before buy
            if self.shares_a > 0:
                if spy_cross_below:
                    self.Liquidate(self.spy)
                    self.shares_a = 0
            else:
                if spy_cross_above:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = int(target_value / spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)
                        self.shares_a = qty

            # Strategy B (AAPL) - sell before buy
            if self.shares_b > 0:
                if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                    self.Liquidate(self.aapl)
                    self.shares_b = 0
            else:
                if self.aapl_red_streak >= 3:
                    cash_needed = 20000.0
                    if self.Portfolio.Cash >= cash_needed:
                        qty = int(cash_needed / aapl_close)
                        if qty > 0:
                            self.MarketOrder(self.aapl, qty)
                            self.shares_b = qty

        # Update previous-day snapshots for next bar's cross detection.
        if spy_present and self.spy_sma.IsReady:
            self.prev_spy_close = spy_close
            self.prev_spy_sma = spy_sma_val
        if aapl_present:
            self.prev_aapl_close = aapl_close

