class DualSlotParallelStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.tracked_symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Strategy A (SPY) state
        self.spy_sma = self.SMA(self.spy, 50, Resolution.Daily)
        self.spy_prev_close = None
        self.spy_prev_sma = None
        self.spy_cross_above_today = False
        self.spy_cross_below_today = False

        # Strategy B (AAPL) state
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)
        self.aapl_prev_close = None
        self.aapl_red_streak = 0
        self.aapl_bar_count = 0

        self.spy_invest_pct = 0.40
        self.aapl_buy_amount = 20000.0
        self.rsi_sell_level = 60.0
        self.red_streak_threshold = 3

    def OnData(self, data: Slice):
        # Market state is always updated from available data, independent of whether
        # today's rule evaluation ends up being skipped.
        self.UpdateSpyState(data)
        self.UpdateAaplState(data)

        if not self.AllTickersPresentToday(data):
            return

        if not self.IndicatorsReady():
            return

        # Sells before buys, slots evaluated independently.
        self.EvaluateStrategyA(data)
        self.EvaluateStrategyB(data)

    def UpdateSpyState(self, data: Slice):
        if not data.Bars.ContainsKey(self.spy):
            self.spy_cross_above_today = False
            self.spy_cross_below_today = False
            return

        close = data.Bars[self.spy].Close
        self.spy_cross_above_today = False
        self.spy_cross_below_today = False

        if self.spy_sma.IsReady:
            sma_val = self.spy_sma.Current.Value
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                self.spy_cross_above_today = self.spy_prev_close <= self.spy_prev_sma and close > sma_val
                self.spy_cross_below_today = self.spy_prev_close >= self.spy_prev_sma and close < sma_val
            self.spy_prev_close = close
            self.spy_prev_sma = sma_val

    def UpdateAaplState(self, data: Slice):
        if not data.Bars.ContainsKey(self.aapl):
            return

        close = data.Bars[self.aapl].Close
        self.aapl_bar_count += 1
        if self.aapl_prev_close is not None:
            if close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_prev_close = close

    def AllTickersPresentToday(self, data: Slice) -> bool:
        for sym in self.tracked_symbols:
            if not data.Bars.ContainsKey(sym):
                return False
        return True

    def IndicatorsReady(self) -> bool:
        if not self.spy_sma.IsReady:
            return False
        if not self.aapl_rsi.IsReady:
            return False
        if self.aapl_bar_count < 4:
            return False
        if self.spy_prev_close is None or self.spy_prev_sma is None:
            return False
        return True

    def EvaluateStrategyA(self, data: Slice):
        lot_qty = self.Portfolio[self.spy].Quantity

        if lot_qty > 0:
            if self.spy_cross_below_today:
                self.Liquidate(self.spy)
        else:
            if self.spy_cross_above_today:
                self.SetHoldings(self.spy, self.spy_invest_pct)

    def EvaluateStrategyB(self, data: Slice):
        lot_qty = self.Portfolio[self.aapl].Quantity

        if lot_qty > 0:
            if self.aapl_rsi.Current.Value > self.rsi_sell_level:
                self.Liquidate(self.aapl)
        else:
            if self.aapl_red_streak >= self.red_streak_threshold:
                if self.Portfolio.Cash >= self.aapl_buy_amount:
                    price = data.Bars[self.aapl].Close
                    shares = int(self.aapl_buy_amount // price)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)

