        if not data.Bars.ContainsKey(self.aapl):
            return

        close = data.Bars[self.aapl].Close
        self.aapl_bar_count += 1
        if self.aapl_prev_close is not None:
            if close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_prev_close = close

    def AllTickersPresentToday(self, data: Slice) -> bool:
        for sym in self.tracked_symbols:
            if not data.Bars.ContainsKey(sym):
                return False
        return True

    def IndicatorsReady(self) -> bool:
        if not self.spy_sma.IsReady:
            return False
        if not self.aapl_rsi.IsReady:
            return False
        if self.aapl_bar_count < 4:
            return False
        if self.spy_prev_close is None or self.spy_prev_sma is None:
            return False
        return True

    def EvaluateStrategyA(self, data: Slice):
        lot_qty = self.Portfolio[self.spy].Quantity

        if lot_qty > 0:
            if self.spy_cross_below_today:
                self.Liquidate(self.spy)
        else:
            if self.spy_cross_above_today:
                self.SetHoldings(self.spy, self.spy_invest_pct)

    def EvaluateStrategyB(self, data: Slice):
        lot_qty = self.Portfolio[self.aapl].Quantity

        if lot_qty > 0:
            if self.aapl_rsi.Current.Value > self.rsi_sell_level:
                self.Liquidate(self.aapl)
        else:
            if self.aapl_red_streak >= self.red_streak_threshold:
                if self.Portfolio.Cash >= self.aapl_buy_amount:
                    price = data.Bars[self.aapl].Close
                    shares = int(self.aapl_buy_amount // price)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
