        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(60, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        if aapl_bar is not None:
            if self.prev_aapl_close is not None:
                if aapl_bar.Close < self.prev_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.prev_aapl_close = aapl_bar.Close

        if self.IsWarmingUp:
            if spy_bar is not None and self.spy_sma.IsReady:
                self.prev_spy_close = spy_bar.Close
                self.prev_spy_sma = self.spy_sma.Current.Value
            return

        all_present = all(
            data.Bars.ContainsKey(s) and data.Bars[s] is not None for s in self.symbols
        )

        if (all_present and self.spy_sma.IsReady and self.aapl_rsi.IsReady
                and self.prev_spy_close is not None and self.prev_spy_sma is not None):

