        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in tickers:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy_symbol = self.symbols["SPY"]
        self.aapl_symbol = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy_symbol, self.SPY_SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl_symbol, self.AAPL_RSI_PERIOD, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_prev_close = None
        self.aapl_red_streak = 0

        self.spy_lot_shares = 0
        self.aapl_lot_shares = 0

        self.SetWarmUp(max(self.SPY_SMA_PERIOD, self.AAPL_RSI_PERIOD) + 1, Resolution.Daily)

    def OnData(self, slice: Slice):
        for symbol in self.symbols.values():
            if not slice.Bars.ContainsKey(symbol):
                return

        spy_close = slice.Bars[self.spy_symbol].Close
        aapl_close = slice.Bars[self.aapl_symbol].Close

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.IsWarmingUp or not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self.spy_prev_close = spy_close
            self.spy_prev_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            self.aapl_prev_close = aapl_close
            return

        spy_sma_value = self.spy_sma.Current.Value

        # Strategy A - SPY (sell before buy; lot state makes these mutually exclusive)
        if self.spy_lot_shares > 0:
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                crossed_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < spy_sma_value)
                if crossed_below:
                    self.MarketOrder(self.spy_symbol, -self.spy_lot_shares)
                    self.spy_lot_shares = 0
        else:
            if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                crossed_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > spy_sma_value)
                if crossed_above:
                    target_value = self.Portfolio.TotalPortfolioValue * self.SPY_INVEST_PCT
                    shares = int(target_value // spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy_symbol, shares)
                        self.spy_lot_shares = shares

        # Strategy B - AAPL (sell before buy; lot state makes these mutually exclusive)
        if self.aapl_lot_shares > 0:
            if self.aapl_rsi.Current.Value > self.AAPL_RSI_SELL_LEVEL:
                self.MarketOrder(self.aapl_symbol, -self.aapl_lot_shares)
                self.aapl_lot_shares = 0
        else:
            if self.aapl_red_streak >= self.AAPL_RED_STREAK:
                available_cash = self.Portfolio.Cash
                if available_cash >= self.AAPL_BUY_AMOUNT:
                    shares = int(self.AAPL_BUY_AMOUNT // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl_symbol, shares)
                        self.aapl_lot_shares = shares

        self.spy_prev_close = spy_close
        self.spy_prev_sma = spy_sma_value
        self.aapl_prev_close = aapl_close

