            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Strategy A indicator
        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)

        # Strategy B indicator
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Manually tracked previous-bar values, needed to detect crosses
        self.prev_spy_close = None
        self.prev_sma = None

        # AAPL consecutive red-day streak tracking
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        # Skip ALL rule evaluation for the day if any subscribed ticker's bar is missing
        for symbol in self.symbols.values():
            if not data.Bars.ContainsKey(symbol):
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # Update AAPL red-day streak (market-state, computed continuously)
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        # ---------------- Slot 1 - Strategy A (SPY, 100-day SMA cross) ----------------
        if self.sma100.IsReady:
            sma_value = self.sma100.Current.Value
            spy_quantity = self.Portfolio[self.spy].Quantity

            if self.prev_spy_close is not None and self.prev_sma is not None:
                # Sells before buys
                if spy_quantity > 0:
                    if self.prev_spy_close >= self.prev_sma and spy_close < sma_value:
                        self.Liquidate(self.spy, tag="StrategyA sell")
                        spy_quantity = 0

                if spy_quantity == 0:
                    if self.prev_spy_close <= self.prev_sma and spy_close > sma_value:
                        target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                        quantity = math.floor(target_value / spy_close)
                        if quantity > 0:
                            self.MarketOrder(self.spy, quantity, tag="StrategyA buy")

            self.prev_sma = sma_value

        self.prev_spy_close = spy_close

        # ---------------- Slot 2 - Strategy B (AAPL, red streak / RSI) ----------------
        aapl_quantity = self.Portfolio[self.aapl].Quantity

        # Sells before buys
        if aapl_quantity > 0 and self.rsi14.IsReady:
            if self.rsi14.Current.Value > 60:
                self.Liquidate(self.aapl, tag="StrategyB sell")
                aapl_quantity = 0

        if aapl_quantity == 0:
            if self.aapl_red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    quantity = math.floor(20000 / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity, tag="StrategyB buy")

        self.prev_aapl_close = aapl_close

