        self.smaSPY = self.SMA(self.spy, 100, Resolution.Daily)
        self.prevCloseSPY = None
        self.prevSmaSPY = None
        self.lotA = 0  # shares owned by Strategy A

        # --- Slot 2 - Strategy B (AAPL) ---
        self.rsiAAPL = self.RSI(self.aapl, 14, Resolution.Daily, MovingAverageType.Wilders)
        self.prevCloseAAPL = None
        self.redStreakAAPL = 0
        self.lotB = 0  # shares owned by Strategy B

    def OnData(self, data: Slice):
        # Skip all rule evaluation for the day if any subscribed ticker's bar is missing.
        for sym in self.symbols.values():
            if not data.Bars.ContainsKey(sym):
                return

        closeSPY = data.Bars[self.spy].Close
        closeAAPL = data.Bars[self.aapl].Close

        # ===================== Strategy A (SPY) =====================
        if self.smaSPY.IsReady:
            currentSmaSPY = self.smaSPY.Current.Value

            if self.prevSmaSPY is not None and self.prevCloseSPY is not None:
                crossesAbove = (self.prevCloseSPY <= self.prevSmaSPY) and (closeSPY > currentSmaSPY)
                crossesBelow = (self.prevCloseSPY >= self.prevSmaSPY) and (closeSPY < currentSmaSPY)

                # Evaluate sell before buy.
                if self.lotA > 0:
                    if crossesBelow:
                        self.MarketOrder(self.spy, -self.lotA)
                        self.lotA = 0
                elif self.lotA == 0:
                    if crossesAbove:
                        targetValue = self.Portfolio.TotalPortfolioValue * 0.40
                        qty = math.floor(targetValue / closeSPY)
                        if qty > 0:
                            self.MarketOrder(self.spy, qty)
                            self.lotA += qty

            self.prevSmaSPY = currentSmaSPY
            self.prevCloseSPY = closeSPY

        # ===================== Strategy B (AAPL) =====================
        if self.prevCloseAAPL is not None:
            if closeAAPL < self.prevCloseAAPL:
                self.redStreakAAPL += 1
            else:
                self.redStreakAAPL = 0

            # Evaluate sell before buy.
            if self.lotB > 0:
                if self.rsiAAPL.IsReady and self.rsiAAPL.Current.Value > 60:
                    self.MarketOrder(self.aapl, -self.lotB)
                    self.lotB = 0
            elif self.lotB == 0:
                if self.redStreakAAPL >= 3:
                    availableCash = self.Portfolio.Cash
                    if availableCash >= 20000:
                        qty = math.floor(20000 / closeAAPL)
                        if qty > 0:
                            self.MarketOrder(self.aapl, qty)
                            self.lotB += qty
                    # else: do nothing this bar; reason may fire again later.

        self.prevCloseAAPL = closeAAPL

