    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Slot 1 (Strategy A) indicator
        self.sma100 = self.SMA(self.spy, 100, Resolution.Daily)

        # Slot 2 (Strategy B) indicator
        self.rsi14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.SetWarmUp(100, Resolution.Daily)

        # Continuously-tracked market state for cross detection (Strategy A)
        self.spy_prev_close = None
        self.spy_prev_sma = None

        # Continuously-tracked market state for red-day streak (Strategy B)
        self.aapl_prev_close = None
        self.aapl_red_streak = 0

    def OnData(self, slice: Slice):
        spy_cross_above = False
        spy_cross_below = False

        # Update SPY close/SMA state continuously (independent of missing-data skip)
        if self.spy in slice.Bars:
            spy_bar = slice.Bars[self.spy]
            today_close = spy_bar.Close
            if self.sma100.IsReady:
                today_sma = self.sma100.Current.Value
                if self.spy_prev_close is not None and self.spy_prev_sma is not None:
                    spy_cross_above = self.spy_prev_close <= self.spy_prev_sma and today_close > today_sma
                    spy_cross_below = self.spy_prev_close >= self.spy_prev_sma and today_close < today_sma
                self.spy_prev_close = today_close
                self.spy_prev_sma = today_sma

        # Update AAPL red-day streak continuously (independent of missing-data skip)
        if self.aapl in slice.Bars:
            aapl_bar = slice.Bars[self.aapl]
